 FrameworkElement RadioChoice(string label,string name,string[] choices,Action changed){var row=new DockPanel{MinHeight=32};row.Children.Add(new TextBlock{Text=label,Width=89,VerticalAlignment=VerticalAlignment.Center});var options=new WrapPanel{VerticalAlignment=VerticalAlignment.Center};row.Children.Add(options);string group=Guid.NewGuid().ToString();for(int i=0;i<choices.Length;i++){int index=i;var button=new RadioButton{Content=choices[i],GroupName=group,IsChecked=values[name].GetInt32()==index,Focusable=true,VerticalAlignment=VerticalAlignment.Center,Margin=choices.Length==2?new(2,0,0,0):new(0),Tag="ImageBinaryChoice:"+name+":"+index};button.Checked+=(_,_)=>{values[name]=JsonSerializer.SerializeToElement(index);changed();CommitLive();};options.Children.Add(button);}return row;}
