 static string FieldLabel(string name)=>name switch{"ROICenterX"=>"中心X","ROICenterY"=>"中心Y","ROIWidth"=>"宽","ROIHeight"=>"高","ROIAngle"=>"角度","ROIAnnulusCenterX"=>"圆心X","ROIAnnulusCenterY"=>"圆心Y","ROIAnnulusInnerRadius"=>"内半径","ROIAnnulusOuterRadius"=>"外半径","ROIAnnulusStartAngle"=>"起始角度","ROIAnnulusAngleExtend"=>"角度范围","BaseX"=>"基准X","BaseY"=>"基准Y","Angle"=>"基准角度","ScaleX"=>"基准缩放X","ScaleY"=>"基准缩放Y","RunPointBaseX"=>"运行X","RunPointBaseY"=>"运行Y","RunAngle"=>"运行角度","RunScaleX"=>"运行缩放X","RunScaleY"=>"运行缩放Y",_=>name};
 void Clear(IEnumerable<string> names){foreach(var name in names){if(context.ApplyConfigurationChange is not null)pendingClears.Add(name);else context.ClearInput?.Invoke(name);if(regionFields.TryGetValue(name,out var field)){field.IsEnabled=true;field.Input.Text=values[name].GetDouble().ToString("G",System.Globalization.CultureInfo.InvariantCulture);}}}
